 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Column-wise periodic background; derive period and phase from the clean
    # right-hand portion of row zero. The first column has a special top cell.
    period = max(v for row in grid for v in row if v != 0)
    # These patterns cycle through 1..period; in this task's palette, col 1
    # is one greater than the period's maximum.
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                out[r][c] = (c + period - 1) % period + 1
                if c == 0 and r > 0:
                    out[r][c] = period
    return out
"
